UPDATE mdl_provider
SET status = #{decision.status},
    approval_evidence_schema = NULL,
    approval_evidence_digest = NULL,
    approval_target_digest = NULL,
    updated_at = #{decision.updatedAt},
    version = #{expectedVersion} + 1
WHERE tenant_id = #{decision.tenantId}
  AND id = #{decision.id}
  AND deleted_at IS NULL
  AND version = #{expectedVersion}
  AND status = #{expectedStatus}
  AND approval_request_id = #{expectedApprovalRequestId}
  AND approval_evidence_schema = 'model-approval-evidence/v1'
  AND approval_evidence_digest = #{expectedEvidenceDigest}
  AND approval_target_digest = #{expectedTargetDigest}
